package cl.dynasty.nexusbeacon.platform.classic;
import java.util.ArrayList;import java.util.List;import org.bukkit.ChatColor;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;import cl.dynasty.nexusbeacon.platform.api.ItemIdentity;import cl.dynasty.nexusbeacon.platform.api.ItemIdentityService;
public final class ClassicBeaconItemFactory { private final ItemIdentityService identities;private final String name;private final List<String> lore;
 public ClassicBeaconItemFactory(ItemIdentityService i,String n,List<String> l){identities=i;name=n;lore=new ArrayList<String>(l);}
 public ItemStack createNew(int amount){return mark(decorate(new ItemStack(Material.BEACON,amount),null));} public ItemStack createPortable(ClassicBeaconRecord r){return mark(decorate(new ItemStack(Material.BEACON),r));}
 private ItemStack mark(ItemStack i){return identities.mark(i,ItemIdentity.NEXUS_BEACON);} private ItemStack decorate(ItemStack i,ClassicBeaconRecord r){ItemMeta m=i.getItemMeta();if(m!=null){m.setDisplayName(color(name));List<String> lines=new ArrayList<String>();if(r==null)for(String x:lore)lines.add(color(x));else{lines.add(color("&7Owner: &f"+(r.getOwner()==null?"None":r.getOwner())));lines.add(color("&7Range: &f"+r.getRange()));lines.add(color("&7Effects: &f"+r.getEffects().size()));}m.setLore(lines);i.setItemMeta(m);}return i;} private static String color(String s){return ChatColor.translateAlternateColorCodes('&',s==null?"":s);}}
